async function FetchQueue(old_account, eic, aUser) {
  let param = null
  param = eic ? eic : old_account ? old_account : null
  //const token = await grecaptcha('/api/number_queue/')
  const token = await getTurnstileToken();
  if (!token) {
    alert('Підтвердіть, що ви не робот');
    return;
  }

  let queue = 0;
  let queue_cc = '';

  if (!param) return;

  try {
    const response = await fetch(`/api/number_queue/`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ search_param: param, token: token || null })
    });
